{"issue": true, "summary": "The rawBody function does not properly handle the case where a parser throws an error during body processing, leading to unhandled exceptions and potential crashes.", "edits": [{"path": "lib/content-type-parser.js", "old": "    const result = parser.fn(request, body, done)
    if (result && typeof result.then === 'function') {
      result.then(body => { done(null, body) }, done)
    }", "new": "    try {
      const result = parser.fn(request, body, done)
      if (result && typeof result.then === 'function') {
        result.then(body => { done(null, body) }, done)
      }
    } catch (err) {
      done(err, undefined)
    }"}]}
